import numpy as np
import time
from scipy.optimize import minimize


def _initial_hex():
    counts = [6, 5, 6, 5, 6, 4]
    dy = np.sqrt(3.0) / 2.0 * (1.0 / 6.0)
    y0 = (1.0 - 5.0 * dy) / 2.0
    centers = []
    for j, n in enumerate(counts):
        y = y0 + j * dy
        for i in range(n):
            if n == 6:
                x = (i + 0.5) / 6.0
            elif n == 5:
                x = (i + 1.0) / 6.0
            else:
                x = (i + 0.5) / 4.0
            centers.append((x, y))
    return np.array(centers)


def _radii_from_clearance(centers):
    n = len(centers)
    r = np.zeros(n)
    for i in range(n):
        x, y = centers[i]
        best = min(x, 1.0 - x, y, 1.0 - y)
        for j in range(n):
            if j == i:
                continue
            d = np.hypot(x - centers[j][0], y - centers[j][1])
            if d < best:
                best = d
        r[i] = 0.95 * 0.5 * best
    return r


def _pack(z):
    n = len(z) // 3
    return z[:n], z[n:2 * n], z[2 * n:3 * n]


def _objective(z):
    _, _, r = _pack(z)
    return -np.sum(r)


def _constraints(z):
    n = len(z) // 3
    x, y, r = _pack(z)
    cons = []
    # walls
    cons.append(x - r)
    cons.append(1.0 - x - r)
    cons.append(y - r)
    cons.append(1.0 - y - r)
    # pairwise
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            cons.append(d - r[i] - r[j])
    return np.concatenate(cons)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.5

    centers = _initial_hex()
    radii = _radii_from_clearance(centers)

    z0 = np.concatenate([centers[:, 0], centers[:, 1], radii])

    bounds = [(0.0, 1.0)] * 64 + [(1e-6, 0.5)] * 32
    cons = {'type': 'ineq', 'fun': _constraints}

    best_z = z0.copy()
    best_val = _objective(z0)

    try:
        res = minimize(_objective, z0, method='SLSQP', bounds=bounds,
                       constraints=cons,
                       options={'maxiter': 500, 'ftol': 1e-12})
        if res.fun < best_val:
            best_val = res.fun
            best_z = res.x
    except Exception:
        pass

    x, y, r = _pack(best_z)
    out = np.column_stack([x, y, r])

    # safety: shrink radii slightly and clamp
    out[:, 2] = np.maximum(out[:, 2] - 1e-8, 1e-9)
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])

    # verify and shrink further if needed
    for _ in range(5):
        ok = True
        for i in range(32):
            xi, yi, ri = out[i]
            if ri <= 0 or xi - ri < 0 or xi + ri > 1 or yi - ri < 0 or yi + ri > 1:
                ok = False
                break
        if ok:
            for i in range(32):
                for j in range(i + 1, 32):
                    d = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
                    if d < out[i, 2] + out[j, 2]:
                        ok = False
                        break
                if not ok:
                    break
        if ok:
            break
        out[:, 2] = np.maximum(out[:, 2] * 0.999, 1e-9)

    return out
